'use strict';

// Renders the inline part of a comment body: the span level markup that is
// allowed inside a paragraph. Block structure lives in src/comment.js.
//
// The author's text arrives as a plain string straight off the compose box and
// the return value is dropped into the thread view template.

function renderInline(src) {
  let out = String(src);
  out = out.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  out = out.replace(/\*(.+?)\*/g, '<em>$1</em>');
  out = out.replace(/`(.+?)`/g, '<code>$1</code>');
  out = out.replace(/\[(.+?)\]\((.+?)\)/g, '<a href="$2">$1</a>');
  return out;
}

module.exports = { renderInline };

