'use strict';

const { renderInline } = require('./inline.js');

// Renders a whole comment body for the thread view. Blank lines separate
// paragraphs; everything inside a paragraph is inline markup.
function renderComment(body) {
  return String(body)
    .split(/\n{2,}/)
    .map((paragraph) => '<p>' + renderInline(paragraph) + '</p>')
    .join('\n');
}

module.exports = { renderComment };

