'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { renderInline, plainText } = require('./src/inline.js');
const { renderComment } = require('./src/comment.js');

test('s1 the author text is HTML escaped and the renderer own tags are not', () => {
  assert.strictEqual(renderInline('a < b & c > d'), 'a &lt; b &amp; c &gt; d');
  assert.strictEqual(renderInline('he said "no"'), 'he said &quot;no&quot;');
  assert.strictEqual(
    renderInline('<script>alert(1)</script>'),
    '&lt;script&gt;alert(1)&lt;/script&gt;',
    'a pasted tag reaches the page as text, not as a tag'
  );
  assert.strictEqual(renderInline('5 > 3 && 2 < 4'), '5 &gt; 3 &amp;&amp; 2 &lt; 4');
  assert.strictEqual(
    renderInline('&amp;'),
    '&amp;amp;',
    'an entity the author typed reads back as they typed it'
  );

  // The em and strong tags are the renderer's own and stay real tags.
  assert.strictEqual(renderInline('*a* & <b>'), '<em>a</em> &amp; &lt;b&gt;');
  assert.strictEqual(renderInline('**a** > **b**'), '<strong>a</strong> &gt; <strong>b</strong>');
  assert.strictEqual(renderInline('plain words'), 'plain words');
});

test('s2 a code span wins over every other kind of markup inside it', () => {
  assert.strictEqual(renderInline('`a * b * c`'), '<code>a * b * c</code>');
  assert.strictEqual(renderInline('a `*x*` b'), 'a <code>*x*</code> b');
  assert.strictEqual(
    renderInline('*before* `and *inside*`'),
    '<em>before</em> <code>and *inside*</code>',
    'emphasis outside the backticks still renders'
  );
  assert.strictEqual(
    renderInline('`[a](/u)`'),
    '<code>[a](/u)</code>',
    'link syntax inside a code span is characters, not a link'
  );
  assert.strictEqual(
    renderInline('`<b>&"</b>`'),
    '<code>&lt;b&gt;&amp;&quot;&lt;/b&gt;</code>',
    'code span content is escaped like any other author text'
  );
  assert.strictEqual(renderInline('`**not strong**`'), '<code>**not strong**</code>');
});

test('s3 a code span opens and closes on backtick runs of the same length', () => {
  assert.strictEqual(
    renderInline('`` a ` b ``'),
    '<code>a ` b</code>',
    'a double run holds a single backtick, and one space comes off each end'
  );
  assert.strictEqual(renderInline('```x```'), '<code>x</code>');
  assert.strictEqual(renderInline('``code``'), '<code>code</code>');
  assert.strictEqual(
    renderInline('a ` b'),
    'a ` b',
    'a run that never finds its match is not a code span'
  );
  assert.strictEqual(renderInline('``a`'), '``a`', 'runs of different lengths do not pair up');
  assert.strictEqual(
    renderInline('`  a  `'),
    '<code> a </code>',
    'exactly one space comes off each end, not all of them'
  );
  assert.strictEqual(
    renderInline('` `'),
    '<code> </code>',
    'content that is all spaces is left alone'
  );
  assert.strictEqual(renderInline('`a`'), '<code>a</code>');
});

test('s4 emphasis nests and stacks by delimiter run length', () => {
  assert.strictEqual(renderInline('*em*'), '<em>em</em>');
  assert.strictEqual(renderInline('**strong**'), '<strong>strong</strong>');
  assert.strictEqual(renderInline('***both***'), '<em><strong>both</strong></em>');

  assert.strictEqual(renderInline('_em_'), '<em>em</em>', 'underscores are delimiters too');
  assert.strictEqual(renderInline('__strong__'), '<strong>strong</strong>');
  assert.strictEqual(renderInline('___both___'), '<em><strong>both</strong></em>');

  assert.strictEqual(renderInline('**a *b* c**'), '<strong>a <em>b</em> c</strong>');
  assert.strictEqual(renderInline('*a **b** c*'), '<em>a <strong>b</strong> c</em>');
  assert.strictEqual(renderInline('*a**b**c*'), '<em>a<strong>b</strong>c</em>');
  assert.strictEqual(renderInline('__a _b_ c__'), '<strong>a <em>b</em> c</strong>');

  assert.strictEqual(
    renderInline('**one** and **two**'),
    '<strong>one</strong> and <strong>two</strong>',
    'one pair sits next to another'
  );
  assert.strictEqual(renderInline('*a* *b*'), '<em>a</em> <em>b</em>');

  assert.strictEqual(
    renderInline('****x****'),
    '****x****',
    'a run of four or more has no meaning'
  );
  assert.strictEqual(renderInline('**a*'), '**a*', 'runs of different lengths do not pair up');
});

test('s5 a backslash makes the next punctuation character literal', () => {
  assert.strictEqual(renderInline('\\*not em\\*'), '*not em*');
  assert.strictEqual(renderInline('\\_not em\\_'), '_not em_');
  assert.strictEqual(
    renderInline('\\[a\\](/u)'),
    '[a](/u)',
    'an escaped bracket does not open a link'
  );
  assert.strictEqual(renderInline('a \\\\ b'), 'a \\ b', 'a backslash escapes a backslash');
  assert.strictEqual(
    renderInline('\\a'),
    '\\a',
    'a backslash before a letter is just a backslash'
  );
  assert.strictEqual(renderInline('a\\'), 'a\\', 'a trailing backslash is just a backslash');
  assert.strictEqual(
    renderInline('\\&'),
    '&amp;',
    'an escaped ampersand is a literal ampersand, and still gets escaped for the page'
  );
  assert.strictEqual(renderInline('\\<b\\>'), '&lt;b&gt;');
  assert.strictEqual(
    renderInline('`\\*`'),
    '<code>\\*</code>',
    'inside a code span a backslash is a character'
  );
  assert.strictEqual(renderInline('\\*a\\* and *b*'), '*a* and <em>b</em>');
});

test('s6 a link renders its label as markup and escapes its destination', () => {
  assert.strictEqual(renderInline('[text](/url)'), '<a href="/url">text</a>');
  assert.strictEqual(
    renderInline('[**bold** and `code`](/u)'),
    '<a href="/u"><strong>bold</strong> and <code>code</code></a>',
    'the label is inline markup in its own right'
  );
  assert.strictEqual(
    renderInline('[a](/x?y=1&z=2)'),
    '<a href="/x?y=1&amp;z=2">a</a>',
    'the destination is escaped as an attribute value'
  );
  assert.strictEqual(renderInline('[a](/x"y)'), '<a href="/x&quot;y">a</a>');
  assert.strictEqual(renderInline('*[a](/u)*'), '<em><a href="/u">a</a></em>');
  assert.strictEqual(
    renderInline('[a [b] c](/u)'),
    '<a href="/u">a [b] c</a>',
    'brackets nest inside a label'
  );

  assert.strictEqual(renderInline('[unclosed'), '[unclosed');
  assert.strictEqual(renderInline('[a]'), '[a]', 'a label with no destination is not a link');
  assert.strictEqual(renderInline('[a] (/u)'), '[a] (/u)');
  assert.strictEqual(
    renderInline('[a](/x'),
    '[a](/x',
    'a parenthesis that never closes is not a link'
  );
});

test('s7 a link takes an optional quoted title', () => {
  assert.strictEqual(renderInline('[t](/u "Tip")'), '<a href="/u" title="Tip">t</a>');
  assert.strictEqual(renderInline("[t](/u 'Tip')"), '<a href="/u" title="Tip">t</a>');
  assert.strictEqual(
    renderInline('[t](/u "a & b")'),
    '<a href="/u" title="a &amp; b">t</a>',
    'the title is escaped as an attribute value'
  );
  assert.strictEqual(
    renderInline('[t](/u "say \\"hi\\"")'),
    '<a href="/u" title="say &quot;hi&quot;">t</a>'
  );
  assert.strictEqual(
    renderInline('[t](  /u  "Tip"  )'),
    '<a href="/u" title="Tip">t</a>',
    'whitespace around the destination and title is not part of either'
  );

  assert.strictEqual(
    renderInline('[t](/u)'),
    '<a href="/u">t</a>',
    'no title means no title attribute at all'
  );
  assert.strictEqual(renderInline('[t]()'), '<a href="">t</a>', 'an empty destination is legal');

  assert.strictEqual(
    renderInline('[t](/u bare)'),
    '[t](/u bare)',
    'something that is not a title in that shape is not a link'
  );
  assert.strictEqual(renderInline('[t](/u "Tip" extra)'), '[t](/u &quot;Tip&quot; extra)');
});

test('s8 a destination carries balanced parentheses, and angle brackets carry the rest', () => {
  assert.strictEqual(
    renderInline('[a](/docs/thing(2))'),
    '<a href="/docs/thing(2)">a</a>',
    'balanced parentheses belong to the destination'
  );
  assert.strictEqual(renderInline('[a](/docs/(a(b)c))'), '<a href="/docs/(a(b)c)">a</a>');
  assert.strictEqual(
    renderInline('[a](/x))'),
    '<a href="/x">a</a>)',
    'the first unbalanced parenthesis closes the link'
  );
  assert.strictEqual(
    renderInline('[a](/x\\(y)'),
    '<a href="/x(y">a</a>',
    'an escaped parenthesis is a character and does not count towards the balance'
  );

  assert.strictEqual(
    renderInline('[a](<my file.pdf>)'),
    '<a href="my file.pdf">a</a>',
    'angle brackets are how a destination with a space in it is written'
  );
  assert.strictEqual(renderInline('[a](<>)'), '<a href="">a</a>');
  assert.strictEqual(renderInline('[a](<a&b>)'), '<a href="a&amp;b">a</a>');
  assert.strictEqual(
    renderInline('[a](<my file.pdf> "T")'),
    '<a href="my file.pdf" title="T">a</a>'
  );
  assert.strictEqual(
    renderInline('[a](/x y)'),
    '[a](/x y)',
    'a bare destination stops at whitespace, so this one never closes'
  );
  assert.strictEqual(
    renderInline('[a](/x(y)'),
    '[a](/x(y)',
    'an opening parenthesis inside the destination has to be balanced too'
  );
});

test('s9 a comment body splits into paragraphs and honours hard line breaks', () => {
  assert.strictEqual(renderComment('one\n\ntwo'), '<p>one</p>\n<p>two</p>');
  assert.strictEqual(
    renderComment('a  \nb'),
    '<p>a<br>\nb</p>',
    'two trailing spaces ask for a break, and never reach the output themselves'
  );
  assert.strictEqual(renderComment('a\nb'), '<p>a\nb</p>', 'a plain newline stays a newline');
  assert.strictEqual(
    renderComment('a  '),
    '<p>a</p>',
    'trailing spaces at the end of a paragraph are not a break'
  );
  assert.strictEqual(
    renderComment('one\n   \ntwo'),
    '<p>one</p>\n<p>two</p>',
    'a line of nothing but spaces is a blank line'
  );
  assert.strictEqual(
    renderComment('\n\none\n\n\n'),
    '<p>one</p>',
    'blank lines at either end do not make empty paragraphs'
  );
  assert.strictEqual(
    renderComment('*a*  \n`b*c`'),
    '<p><em>a</em><br>\n<code>b*c</code></p>',
    'inline markup still renders inside a paragraph'
  );
  assert.strictEqual(renderComment('one\n\n\n\ntwo'), '<p>one</p>\n<p>two</p>');
  assert.strictEqual(renderComment(''), '');
  assert.strictEqual(renderComment('   \n  '), '');
  for (const junk of [null, undefined, 42, {}, []]) {
    assert.strictEqual(renderComment(junk), '', 'a body that is not a string renders nothing');
  }
});

test('s10 an autolink links to itself and anything else in angle brackets is escaped', () => {
  assert.strictEqual(
    renderInline('<https://example.com/x>'),
    '<a href="https://example.com/x">https://example.com/x</a>'
  );
  assert.strictEqual(
    renderInline('<https://example.com/a?b=1&c=2>'),
    '<a href="https://example.com/a?b=1&amp;c=2">https://example.com/a?b=1&amp;c=2</a>'
  );
  assert.strictEqual(
    renderInline('<https://example.com/a_b_c>'),
    '<a href="https://example.com/a_b_c">https://example.com/a_b_c</a>',
    'nothing inside an autolink is markup'
  );
  assert.strictEqual(
    renderInline('<me@example.com>'),
    '<a href="mailto:me@example.com">me@example.com</a>',
    'a bare address gets the scheme in the href and not in the text'
  );
  assert.strictEqual(
    renderInline('<mailto:me@example.com>'),
    '<a href="mailto:me@example.com">mailto:me@example.com</a>',
    'an address written with its scheme keeps the scheme in its text'
  );

  assert.strictEqual(renderInline('<not an autolink>'), '&lt;not an autolink&gt;');
  assert.strictEqual(renderInline('<b>bold</b>'), '&lt;b&gt;bold&lt;/b&gt;');
  assert.strictEqual(renderInline('a < b'), 'a &lt; b');
  assert.strictEqual(
    renderInline('`<https://example.com>`'),
    '<code>&lt;https://example.com&gt;</code>',
    'a code span still wins'
  );
  assert.strictEqual(renderInline('\\<https://example.com\\>'), '&lt;https://example.com&gt;');
  assert.strictEqual(
    renderInline('[a](<https://example.com>)'),
    '<a href="https://example.com">a</a>'
  );
});

test('s11 a delimiter run that cannot pair up stays in the text as written', () => {
  assert.strictEqual(
    renderInline('2 * 3 * 4'),
    '2 * 3 * 4',
    'an opener cannot be followed by whitespace and a closer cannot be preceded by it'
  );
  assert.strictEqual(renderInline('*'), '*');
  assert.strictEqual(renderInline('*loose'), '*loose');
  assert.strictEqual(renderInline('loose*'), 'loose*');
  assert.strictEqual(renderInline('a ** b'), 'a ** b');

  assert.strictEqual(
    renderInline('snake_case_name'),
    'snake_case_name',
    'an underscore run between alphanumerics is neither an opener nor a closer'
  );
  assert.strictEqual(renderInline('a_b_c'), 'a_b_c');
  assert.strictEqual(
    renderInline('a*b*c'),
    'a<em>b</em>c',
    'an asterisk run carries no such restriction'
  );
  assert.strictEqual(renderInline('a _b_ c'), 'a <em>b</em> c');

  assert.strictEqual(
    renderInline('*a ** b*'),
    '<em>a ** b</em>',
    'a run left over inside a pair that did match is still literal'
  );
  assert.strictEqual(renderInline('_ a _'), '_ a _');
  assert.strictEqual(renderInline('one * two ** three'), 'one * two ** three');
  assert.strictEqual(renderInline('*a* * *b*'), '<em>a</em> * <em>b</em>');
});

test('s12 plainText renders the same grammar with the markup taken off', () => {
  assert.strictEqual(plainText('*a* **b** ***c***'), 'a b c');
  assert.strictEqual(
    plainText('`a * b`'),
    'a * b',
    'a code span gives its content, backticks gone and asterisks intact'
  );
  assert.strictEqual(plainText('`` a ` b ``'), 'a ` b', 'the one space trim applies here too');
  assert.strictEqual(plainText('[text](/url "T")'), 'text', 'a link gives its text');
  assert.strictEqual(plainText('**bold with [a link](/u) inside**'), 'bold with a link inside');
  assert.strictEqual(plainText('<https://example.com>'), 'https://example.com');
  assert.strictEqual(
    plainText('<me@example.com>'),
    'me@example.com',
    'the address as it was written, not the mailto form'
  );
  assert.strictEqual(plainText('\\*not em\\*'), '*not em*', 'an escape resolves to its character');
  assert.strictEqual(
    plainText('a < b & c "d"'),
    'a < b & c "d"',
    'nothing on this path reaches a page, so nothing on it is escaped'
  );
  assert.strictEqual(
    plainText('<b>bold</b>'),
    '<b>bold</b>',
    'a pasted tag is text on this path, neither escaped nor swallowed'
  );
  assert.strictEqual(
    plainText('`<b>&"</b>`'),
    '<b>&"</b>',
    'a code span gives its content unescaped too'
  );
  assert.strictEqual(
    plainText('`a</code>b`'),
    'a</code>b',
    'the content is whatever the author typed, however much it looks like a tag'
  );
  assert.strictEqual(
    plainText('&lt;'),
    '&lt;',
    'an entity the author typed is four characters of text, not a less-than sign'
  );
  assert.strictEqual(plainText('&amp;'), '&amp;');
  assert.strictEqual(plainText('2 * 3 * 4'), '2 * 3 * 4');
  assert.strictEqual(plainText('snake_case_name'), 'snake_case_name');
  assert.strictEqual(plainText('****x****'), '****x****');
  assert.strictEqual(plainText(''), '');
  for (const junk of [null, undefined, 42, {}, []]) {
    assert.strictEqual(plainText(junk), '', 'anything that is not a string is an empty string');
  }

  // The HTML path is untouched by any of this.
  assert.strictEqual(renderInline('*a* & <b>'), '<em>a</em> &amp; &lt;b&gt;');
  assert.strictEqual(renderInline('[t](/u "Tip")'), '<a href="/u" title="Tip">t</a>');
});

