'use strict';

// Renders the inline part of a comment body: the span level markup that is
// allowed inside a paragraph. Block structure lives in src/comment.js.
//
// The author's text arrives as a plain string straight off the compose box and
// the return value is dropped into the thread view template, so escaping is a
// property of the serializer rather than a pass over the finished HTML: the
// tags below are ours, everything that came from the author is escaped.

const ESCAPABLE = '!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~';

const AUTOLINK_URI = /^<([A-Za-z][A-Za-z0-9+.\-]{1,31}:[^<>\s]*)>/;
const AUTOLINK_EMAIL =
  /^<([A-Za-z0-9.!#$%&'*+\/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)*)>/;

function escapeHtml(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function isSpace(ch) {
  return ch !== '' && /\s/.test(ch);
}

function isAlnum(ch) {
  return ch !== '' && /[0-9A-Za-z]/.test(ch);
}

function isEscapable(ch) {
  return typeof ch === 'string' && ch.length === 1 && ESCAPABLE.indexOf(ch) !== -1;
}

function runLength(src, i, ch) {
  let n = 0;
  while (i + n < src.length && src[i + n] === ch) n += 1;
  return n;
}

// A code span opens on a run of backticks and closes on the next run of exactly
// the same length. Nothing inside it is markup.
function scanCodeSpan(src, i) {
  const openLen = runLength(src, i, '`');
  let j = i + openLen;
  while (j < src.length) {
    if (src[j] !== '`') {
      j += 1;
      continue;
    }
    const closeLen = runLength(src, j, '`');
    if (closeLen === openLen) {
      let content = src.slice(i + openLen, j);
      if (
        content.length >= 2 &&
        content[0] === ' ' &&
        content[content.length - 1] === ' ' &&
        /[^ ]/.test(content)
      ) {
        content = content.slice(1, -1);
      }
      return { node: { type: 'code', value: content }, next: j + closeLen };
    }
    j += closeLen;
  }
  return null;
}

function scanAutolink(src, i) {
  const rest = src.slice(i);
  const uri = AUTOLINK_URI.exec(rest);
  if (uri) {
    return { node: { type: 'autolink', href: uri[1], text: uri[1] }, next: i + uri[0].length };
  }
  const email = AUTOLINK_EMAIL.exec(rest);
  if (email) {
    return {
      node: { type: 'autolink', href: 'mailto:' + email[1], text: email[1] },
      next: i + email[0].length,
    };
  }
  return null;
}

// The ']' that closes the label at src[start], counting nested brackets and
// stepping over escapes and code spans on the way.
function findClosingBracket(src, start) {
  let depth = 0;
  for (let j = start; j < src.length; j += 1) {
    const ch = src[j];
    if (ch === '\\' && isEscapable(src[j + 1])) {
      j += 1;
      continue;
    }
    if (ch === '`') {
      const span = scanCodeSpan(src, j);
      if (span) {
        j = span.next - 1;
        continue;
      }
    }
    if (ch === '[') depth += 1;
    else if (ch === ']') {
      depth -= 1;
      if (depth === 0) return j;
    }
  }
  return -1;
}

function parseDestination(src, i) {
  if (src[i] === '<') {
    let j = i + 1;
    let out = '';
    while (j < src.length) {
      const ch = src[j];
      if (ch === '\\' && isEscapable(src[j + 1])) {
        out += src[j + 1];
        j += 2;
        continue;
      }
      if (ch === '>') return { dest: out, next: j + 1 };
      if (ch === '<' || ch === '\n') return null;
      out += ch;
      j += 1;
    }
    return null;
  }
  let j = i;
  let depth = 0;
  let out = '';
  while (j < src.length) {
    const ch = src[j];
    if (ch === '\\' && isEscapable(src[j + 1])) {
      out += src[j + 1];
      j += 2;
      continue;
    }
    if (isSpace(ch) || ch.charCodeAt(0) < 0x20) break;
    if (ch === '(') depth += 1;
    if (ch === ')') {
      if (depth === 0) break;
      depth -= 1;
    }
    out += ch;
    j += 1;
  }
  if (depth !== 0) return null;
  return { dest: out, next: j };
}

function parseTitle(src, i) {
  const quote = src[i];
  if (quote !== '"' && quote !== "'") return null;
  let j = i + 1;
  let out = '';
  while (j < src.length) {
    const ch = src[j];
    if (ch === '\\' && isEscapable(src[j + 1])) {
      out += src[j + 1];
      j += 2;
      continue;
    }
    if (ch === quote) return { title: out, next: j + 1 };
    out += ch;
    j += 1;
  }
  return null;
}

function skipSpace(src, i) {
  let j = i;
  while (j < src.length && isSpace(src[j])) j += 1;
  return j;
}

function scanLink(src, i) {
  const close = findClosingBracket(src, i);
  if (close < 0) return null;
  if (src[close + 1] !== '(') return null;

  let j = skipSpace(src, close + 2);
  const dest = parseDestination(src, j);
  if (!dest) return null;

  j = dest.next;
  const title = parseTitle(src, skipSpace(src, j));
  if (title) j = title.next;

  j = skipSpace(src, j);
  if (src[j] !== ')') return null;

  return {
    label: src.slice(i + 1, close),
    dest: dest.dest,
    title: title ? title.title : null,
    next: j + 1,
  };
}

function tokenize(src) {
  const nodes = [];
  let text = '';
  const flush = () => {
    if (text !== '') {
      nodes.push({ type: 'text', value: text });
      text = '';
    }
  };

  let i = 0;
  while (i < src.length) {
    const ch = src[i];

    if (ch === '\\' && isEscapable(src[i + 1])) {
      text += src[i + 1];
      i += 2;
      continue;
    }

    if (ch === '`') {
      const span = scanCodeSpan(src, i);
      if (span) {
        flush();
        nodes.push(span.node);
        i = span.next;
        continue;
      }
      const n = runLength(src, i, '`');
      text += '`'.repeat(n);
      i += n;
      continue;
    }

    if (ch === '<') {
      const link = scanAutolink(src, i);
      if (link) {
        flush();
        nodes.push(link.node);
        i = link.next;
        continue;
      }
      text += '<';
      i += 1;
      continue;
    }

    if (ch === '[') {
      const link = scanLink(src, i);
      if (link) {
        flush();
        nodes.push({
          type: 'link',
          dest: link.dest,
          title: link.title,
          children: parse(link.label),
        });
        i = link.next;
        continue;
      }
      text += '[';
      i += 1;
      continue;
    }

    if (ch === '*' || ch === '_') {
      const len = runLength(src, i, ch);
      const before = i > 0 ? src[i - 1] : '';
      const after = i + len < src.length ? src[i + len] : '';
      let canOpen = after !== '' && !isSpace(after);
      let canClose = before !== '' && !isSpace(before);
      if (ch === '_') {
        if (isAlnum(before)) canOpen = false;
        if (isAlnum(after)) canClose = false;
      }
      flush();
      nodes.push({ type: 'delim', ch, len, canOpen, canClose });
      i += len;
      continue;
    }

    text += ch;
    i += 1;
  }

  flush();
  return nodes;
}

function wrapEmphasis(len, children) {
  if (len === 1) return { type: 'em', children };
  if (len === 2) return { type: 'strong', children };
  return { type: 'em', children: [{ type: 'strong', children }] };
}

// A closing run is matched by the nearest still open run of the same character
// and the same length. Anything left over is literal text.
function resolveEmphasis(nodes) {
  for (let i = 0; i < nodes.length; i += 1) {
    const closer = nodes[i];
    if (closer.type !== 'delim' || !closer.canClose || closer.len > 3) continue;
    let open = -1;
    for (let k = i - 1; k >= 0; k -= 1) {
      const cand = nodes[k];
      if (cand.type === 'delim' && cand.canOpen && cand.ch === closer.ch && cand.len === closer.len) {
        open = k;
        break;
      }
    }
    if (open < 0) continue;
    const inner = nodes.slice(open + 1, i);
    nodes.splice(open, i - open + 1, wrapEmphasis(closer.len, inner));
    i = open;
  }
  return nodes;
}

function parse(src) {
  return resolveEmphasis(tokenize(src));
}

function serializeNode(node) {
  switch (node.type) {
    case 'text':
      return escapeHtml(node.value);
    case 'code':
      return '<code>' + escapeHtml(node.value) + '</code>';
    case 'delim':
      return escapeHtml(node.ch.repeat(node.len));
    case 'autolink':
      return '<a href="' + escapeHtml(node.href) + '">' + escapeHtml(node.text) + '</a>';
    case 'link': {
      let out = '<a href="' + escapeHtml(node.dest) + '"';
      if (node.title !== null && node.title !== undefined) {
        out += ' title="' + escapeHtml(node.title) + '"';
      }
      return out + '>' + serialize(node.children) + '</a>';
    }
    case 'em':
      return '<em>' + serialize(node.children) + '</em>';
    case 'strong':
      return '<strong>' + serialize(node.children) + '</strong>';
    default:
      return '';
  }
}

function serialize(nodes) {
  let out = '';
  for (const node of nodes) out += serializeNode(node);
  return out;
}

function flattenNode(node) {
  switch (node.type) {
    case 'text':
    case 'code':
      return node.value;
    case 'delim':
      return node.ch.repeat(node.len);
    case 'autolink':
      return node.text;
    case 'link':
    case 'em':
    case 'strong':
      return flatten(node.children);
    default:
      return '';
  }
}

function flatten(nodes) {
  let out = '';
  for (const node of nodes) out += flattenNode(node);
  return out;
}

function renderInline(src) {
  return serialize(parse(String(src)));
}

// The same grammar with the markup taken off rather than turned into HTML.
// Nothing here reaches a page, so nothing here is escaped.
function plainText(src) {
  if (typeof src !== 'string') return '';
  return flatten(parse(src));
}

module.exports = { renderInline, plainText };

