'use strict';

const { renderInline } = require('./inline.js');

// Renders a whole comment body for the thread view. One or more blank lines
// separate paragraphs; a line carrying nothing but whitespace counts as blank.
// Inside a paragraph a newline stays a newline unless the line it ends was
// padded with two or more spaces, which is the author asking for a break.
function renderComment(body) {
  if (typeof body !== 'string') return '';

  const paragraphs = [];
  let current = [];
  for (const line of body.split(/\r\n|\r|\n/)) {
    if (line.trim() === '') {
      if (current.length) paragraphs.push(current);
      current = [];
      continue;
    }
    current.push(line);
  }
  if (current.length) paragraphs.push(current);

  return paragraphs
    .map((lines) => {
      const rendered = lines.map((line, index) => {
        const hardBreak = index < lines.length - 1 && / {2,}$/.test(line);
        return renderInline(line.replace(/\s+$/, '')) + (hardBreak ? '<br>' : '');
      });
      return '<p>' + rendered.join('\n') + '</p>';
    })
    .join('\n');
}

module.exports = { renderComment };
